<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
function platformAdminAction(string $a,array $d,array $u): array{
 platformAdmin($u);
 if($a==='admin-platform')return ['features'=>platformFeatures(),'variants'=>accountQuery('SELECT * FROM idea_commerce_variants ORDER BY updated_at DESC LIMIT 500')->fetchAll(),'shipping_methods'=>accountQuery('SELECT * FROM idea_shipping_methods ORDER BY name')->fetchAll(),'mail'=>accountQuery('SELECT status,COUNT(*) AS count FROM idea_mail_outbox GROUP BY status')->fetchAll(),'ai'=>accountQuery('SELECT id,user_id,product_id,state,error_code,created_at FROM idea_ai_jobs ORDER BY created_at DESC LIMIT 100')->fetchAll(),'audit'=>accountQuery('SELECT * FROM idea_admin_audit ORDER BY created_at DESC LIMIT 100')->fetchAll(),'refunds'=>accountQuery('SELECT * FROM idea_refunds ORDER BY created_at DESC LIMIT 100')->fetchAll(),'deletion_requests'=>accountQuery('SELECT u.id,u.email,s.deletion_requested_at FROM idea_users u JOIN idea_user_security s ON s.user_id=u.id WHERE s.deletion_requested_at IS NOT NULL')->fetchAll()];
 if($a==='admin-variant-save'){
  $id=accountString($d,'id',32)?:platformId();$product=accountString($d,'product_id',100,true);platformProduct($product);$sku=accountString($d,'sku',100,true);$label=accountString($d,'label',200,true);$evidence=accountString($d,'evidence',1000,true);$unit=accountString($d,'unit',16,true);if(!in_array($unit,['sqm','pieces'],true))accountError(422,'INVALID_UNIT');$price=platformInt($d,'price_cents',1,100000000);$stock=platformInt($d,'stock_milli',0,1000000000);$tax=platformInt($d,'tax_basis_points',0,10000);$company=accountString($d,'company_id',32);if($company&&!accountQuery("SELECT id FROM idea_companies WHERE id=? AND status='verified'",[$company])->fetch())accountError(422,'VERIFIED_COMPANY_REQUIRED');
  return platformTransaction(function()use($id,$product,$sku,$label,$evidence,$unit,$price,$stock,$tax,$company,$d,$u){$old=accountQuery('SELECT * FROM idea_commerce_variants WHERE id=?'.platformLock(),[$id])->fetch();if($old&&(int)$old['reserved_milli']>$stock)accountError(409,'RESERVED_STOCK_EXCEEDS_STOCK');if($old&&($old['product_id']!==$product||$old['company_id']!==($company?:null)||$old['unit']!==$unit))accountError(409,'VARIANT_IDENTITY_IMMUTABLE');$values=[$product,$company?:null,$sku,$label,$unit,$price,$stock,$tax,!empty($d['authorized'])?1:0,!empty($d['active'])?1:0,$evidence,platformNow()];if($old)accountQuery('UPDATE idea_commerce_variants SET product_id=?,company_id=?,sku=?,label=?,unit=?,price_cents=?,stock_milli=?,tax_basis_points=?,authorized=?,active=?,evidence=?,updated_at=? WHERE id=?',array_merge($values,[$id]));else accountQuery('INSERT INTO idea_commerce_variants(product_id,company_id,sku,label,unit,price_cents,stock_milli,tax_basis_points,authorized,active,evidence,updated_at,id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',array_merge($values,[$id]));platformAudit($u,'variant-save',$id);return ['id'=>$id];});
 }
 if($a==='admin-shipping-save'){
  $id=accountString($d,'id',32)?:platformId();$name=accountString($d,'name',160,true);$gov=accountString($d,'governorate',100,true);$price=platformInt($d,'price_cents',0,100000000);$details=accountString($d,'details',2000,true);return platformTransaction(function()use($id,$name,$gov,$price,$details,$d,$u){$values=[$name,$gov,$price,'manual',!empty($d['active'])?1:0,$details];if(accountQuery('SELECT id FROM idea_shipping_methods WHERE id=?',[$id])->fetch())accountQuery('UPDATE idea_shipping_methods SET name=?,governorate=?,price_cents=?,provider=?,active=?,details=? WHERE id=?',array_merge($values,[$id]));else accountQuery('INSERT INTO idea_shipping_methods(name,governorate,price_cents,provider,active,details,id) VALUES(?,?,?,?,?,?,?)',array_merge($values,[$id]));platformAudit($u,'shipping-method-save',$id);return ['id'=>$id];});
 }
 if($a==='admin-setting-save'){$key=accountString($d,'key',100,true);if($key!=='cash_on_delivery'||!is_bool($d['value']??null))accountError(422,'SETTING_NOT_ALLOWED');return platformTransaction(function()use($key,$d,$u){platformPutSetting($key,$d['value']);platformAudit($u,'setting-'.$key,$u['id']);return ['saved'=>true];});}
 if($a==='admin-delivery-save'){
  $id=accountString($d,'order_id',32,true);$tracking=accountString($d,'tracking_number',120,true);$provider=accountString($d,'provider',60,true);$status=accountString($d,'status',40,true);if(!in_array($status,['booked','picked_up','in_transit','out_for_delivery','delivered','failed','returned'],true))accountError(422,'INVALID_DELIVERY_STATE');return platformTransaction(function()use($id,$tracking,$provider,$status,$u){$o=accountQuery('SELECT * FROM idea_orders WHERE id=?'.platformLock(),[$id])->fetch();if(!$o||!in_array($o['status'],['ready_to_ship','shipped','delivered'],true))accountError(409,'ORDER_NOT_READY');$r=accountQuery('SELECT * FROM idea_deliveries WHERE order_id=?',[$id])->fetch();$history=$r?json_decode($r['history'],true):[];$history[]=['status'=>$status,'recorded_by'=>$u['id'],'time'=>platformNow(),'source'=>'administrator'];if($r)accountQuery('UPDATE idea_deliveries SET provider=?,tracking_number=?,status=?,history=?,updated_at=? WHERE id=?',[$provider,$tracking,$status,platformJson($history),platformNow(),$r['id']]);else accountQuery('INSERT INTO idea_deliveries(id,order_id,provider,tracking_number,status,history,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)',[platformId(),$id,$provider,$tracking,$status,platformJson($history),platformNow(),platformNow()]);platformAudit($u,'delivery-update',$id);platformNotify($o['user_id'],'delivery:'.$id.':'.platformNow(),'IDEA — Delivery update',$provider.' / '.$tracking.' / '.$status,'/account/orders/'.$id);return ['saved'=>true];});
 }
 accountError(404,'UNKNOWN_ACTION');
}
